def _parse_tree(text, pos):
    """Parse a GameTree starting at '(' and return (SgfTree, next position)."""
    if pos >= len(text) or text[pos] != "(":
        raise ValueError("tree missing")
    pos += 1
    if pos >= len(text) or text[pos] != ";":
        raise ValueError("tree with no nodes")

    nodes = []
    while pos < len(text) and text[pos] == ";":
        properties, pos = _parse_node(text, pos + 1)
        nodes.append(SgfTree(properties))

    variations = []
    while pos < len(text) and text[pos] == "(":
        child, pos = _parse_tree(text, pos)
        variations.append(child)

    if pos >= len(text) or text[pos] != ")":
        raise ValueError("tree missing")

    # Link the sequence of nodes into a chain; variations hang off the last node.
    for parent, child in zip(nodes, nodes[1:]):
        parent.children.append(child)
    nodes[-1].children.extend(variations)
    return nodes[0], pos + 1


def _parse_node(text, pos):
    properties = {}
    while pos < len(text) and text[pos] not in ";()":
        start = pos
        while pos < len(text) and text[pos].isalpha():
            pos += 1
        key = text[start:pos]
        if not key:
            raise ValueError("properties without delimiter")
        if not key.isupper():
            raise ValueError("property must be in uppercase")
        if pos >= len(text) or text[pos] != "[":
            raise ValueError("properties without delimiter")
        values = []
        while pos < len(text) and text[pos] == "[":
            value, pos = _parse_value(text, pos + 1)
            values.append(value)
        properties.setdefault(key, []).extend(values)
    return properties, pos


def _parse_value(text, pos):
    """Parse an SGF Text value after '[' and return (value, position after ']')."""
    chars = []
    while pos < len(text):
        char = text[pos]
        if char == "]":
            return "".join(chars), pos + 1
        if char == "\\":
            pos += 1
            if pos >= len(text):
                break
            char = text[pos]
            if char == "\n":
                pos += 1
                continue
        if char != "\n" and char.isspace():
            char = " "
        chars.append(char)
        pos += 1
    raise ValueError("properties without delimiter")"}

